package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"reflect"
)

func main() {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, os.Args[1], nil, 0)
	if err != nil {
		panic(err)
	}

	countInspectAll := 0
	ast.Inspect(f, func(n ast.Node) bool {
		if n != nil {
			countInspectAll++
			fmt.Printf("%2d: %T\n", countInspectAll, n)
		}
		return true
	})
	fmt.Printf("Total non-nil nodes: %d\n", countInspectAll)
}
EOF
