{"command":"cat << 'EOF' > /tmp/find_ast_filter.go
package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
)

func main() {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, os.Args[1], nil, 0)
	if err != nil {
		panic(err)
	}

	nodes := []ast.Node{}
	ast.Inspect(f, func(n ast.Node) bool {
		if n != nil {
			nodes = append(nodes, n)
		}
		return true
	})

	fmt.Printf("File: %s, total nodes: %d\n", os.Args[1], len(nodes))
	for i, n := range nodes {
		pos := fset.Position(n.Pos())
		fmt.Printf("%2d: %T at line %d\n", i, n, pos.Line)
	}
}
EOF
go build -o /tmp/find_ast_filter /tmp/find_ast_filter.go
/tmp/find_ast_filter /tmp/token_test/complex1.go"}

