{"command":"cat << 'EOF' > /tmp/ast_walk_test.go
package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
)

func extractTokens(f *ast.File) []ast.Node {
	var tokens []ast.Node
	ast.Inspect(f, func(n ast.Node) bool {
		if n == nil {
			return true
		}
		switch n.(type) {
		case *ast.File, *ast.Comment, *ast.CommentGroup:
			return true
		case *ast.GenDecl:
			if n.(*ast.GenDecl).Tok == token.IMPORT {
				return false // skip import decls and children
			}
		case *ast.ImportSpec:
			return false
		}
		tokens = append(tokens, n)
		return true
	})
	return tokens
}

func main() {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, os.Args[1], nil, 0)
	if err != nil {
		panic(err)
	}

	toks := extractTokens(f)
	fmt.Printf("File: %s -> %d tokens\n", os.Args[1], len(toks))
	for i, t := range toks {
		pos := fset.Position(t.Pos())
		fmt.Printf("%2d: %T at line %d\n", i, t, pos.Line)
	}
}
EOF
go build -o /tmp/ast_walk_test /tmp/ast_walk_test.go
/tmp/ast_walk_test /tmp/token_test/complex1.go"}

