package main

import (
	"bufio"
	"flag"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"html"
	"log"
	"os"
	"path/filepath"
	"reflect"
	"sort"
	"strconv"
	"strings"
)

type Token struct {
	Type    int
	File    string
	PosLine int
	EndLine int
}

type Node struct {
	children  map[int]*Node
	link      *Node
	start     int
	end       *int
	depth     int
	suffixIdx int
	leaves    []int
}

type SuffixTree struct {
	tokens       []int
	root         *Node
	activeNode   *Node
	activeEdge   int
	activeLength int
	remainder    int
	leafEnd      int
}

func NewSuffixTree(tokens []int) *SuffixTree {
	st := &SuffixTree{
		tokens:  tokens,
		leafEnd: -1,
	}
	st.root = &Node{
		children:  make(map[int]*Node),
		start:     -1,
		end:       new(int),
		suffixIdx: -1,
	}
	*st.root.end = -1
	st.activeNode = st.root

	for i := 0; i < len(tokens); i++ {
		st.extend(i)
	}
	st.setSuffixIndices(st.root, 0)
	st.collectLeaves(st.root)
	return st
}

func (st *SuffixTree) edgeLength(node *Node) int {
	if node == st.root {
		return 0
	}
	return *node.end - node.start + 1
}

func (st *SuffixTree) extend(pos int) {
	st.leafEnd = pos
	st.remainder++
	var lastNewNode *Node = nil

	for st.remainder > 0 {
		if st.activeLength == 0 {
			st.activeEdge = pos
		}

		tok := st.tokens[st.activeEdge]
		next, exists := st.activeNode.children[tok]

		if !exists {
			leaf := &Node{
				children:  make(map[int]*Node),
				start:     pos,
				end:       &st.leafEnd,
				suffixIdx: -1,
			}
			st.activeNode.children[tok] = leaf

			if lastNewNode != nil {
				lastNewNode.link = st.activeNode
				lastNewNode = nil
			}
		} else {
			edgeLen := st.edgeLength(next)
			if st.activeLength >= edgeLen {
				st.activeEdge += edgeLen
				st.activeLength -= edgeLen
				st.activeNode = next
				continue
			}

			if st.tokens[next.start+st.activeLength] == st.tokens[pos] {
				if lastNewNode != nil && st.activeNode != st.root {
					lastNewNode.link = st.activeNode
					lastNewNode = nil
				}
				st.activeLength++
				break
			}

			splitEnd := next.start + st.activeLength - 1
			split := &Node{
				children:  make(map[int]*Node),
				start:     next.start,
				end:       &splitEnd,
				link:      st.root,
				suffixIdx: -1,
			}
			st.activeNode.children[tok] = split

			leaf := &Node{
				children:  make(map[int]*Node),
				start:     pos,
				end:       &st.leafEnd,
				suffixIdx: -1,
			}
			split.children[st.tokens[pos]] = leaf
			next.start += st.activeLength
			split.children[st.tokens[next.start]] = next

			if lastNewNode != nil {
				lastNewNode.link = split
			}
			lastNewNode = split
		}

		st.remainder--
		if st.activeNode == st.root && st.activeLength > 0 {
			st.activeLength--
			st.activeEdge = pos - st.remainder + 1
		} else if st.activeNode != st.root {
			if st.activeNode.link != nil {
				st.activeNode = st.activeNode.link
			} else {
				st.activeNode = st.root
			}
		}
	}
}

func (st *SuffixTree) setSuffixIndices(node *Node, currentDepth int) {
	if node == nil {
		return
	}
	if node != st.root {
		currentDepth += *node.end - node.start + 1
	}
	node.depth = currentDepth

	if len(node.children) == 0 {
		node.suffixIdx = len(st.tokens) - currentDepth
		return
	}

	for _, child := range node.children {
		st.setSuffixIndices(child, currentDepth)
	}
}

func (st *SuffixTree) collectLeaves(node *Node) []int {
	if node == nil {
		return nil
	}
	if len(node.children) == 0 {
		node.leaves = []int{node.suffixIdx}
		return node.leaves
	}
	var leaves []int
	for _, child := range node.children {
		leaves = append(leaves, st.collectLeaves(child)...)
	}
	node.leaves = leaves
	return leaves
}

type GroupInfo struct {
	Depth  int
	Leaves []int
}

func (st *SuffixTree) FindMaximalRepeats(threshold int) []GroupInfo {
	var groups []GroupInfo

	isLeftMaximal := func(leaves []int) bool {
		if len(leaves) < 2 {
			return false
		}
		firstPrev := -1
		if leaves[0] > 0 {
			firstPrev = st.tokens[leaves[0]-1]
		}
		for i := 1; i < len(leaves); i++ {
			prev := -1
			if leaves[i] > 0 {
				prev = st.tokens[leaves[i]-1]
			}
			if prev != firstPrev {
				return true
			}
		}
		return false
	}

	var dfs func(node *Node)
	dfs = func(node *Node) {
		if node == nil {
			return
		}

		if node.depth >= threshold && len(node.children) > 0 {
			isRightMaximal := true
			for _, child := range node.children {
				if len(child.children) > 0 && child.depth >= threshold {
					if len(child.leaves) == len(node.leaves) {
						isRightMaximal = false
						break
					}
				}
			}

			if isRightMaximal && len(node.leaves) >= 2 {
				if isLeftMaximal(node.leaves) {
					groups = append(groups, GroupInfo{
						Depth:  node.depth,
						Leaves: append([]int(nil), node.leaves...),
					})
				}
			}
		}

		for _, child := range node.children {
			dfs(child)
		}
	}

	dfs(st.root)
	return groups
}

type Clone struct {
	Filename  string
	StartLine int
	EndLine   int
}

type CloneGroup struct {
	Depth  int
	Clones []Clone
}

var typeMap = make(map[reflect.Type]int)
var nextTypeID = 1

func getTypeId(n ast.Node) int {
	t := reflect.TypeOf(n)
	if id, ok := typeMap[t]; ok {
		return id
	}
	id := nextTypeID
	nextTypeID++
	typeMap[t] = id
	return id
}

func extractFileTokens(fset *token.FileSet, filename string, node *ast.File) []Token {
	var toks []Token
	ast.Inspect(node, func(n ast.Node) bool {
		if n == nil {
			return true
		}
		switch n.(type) {
		case *ast.File, *ast.Comment, *ast.CommentGroup:
			return true
		case *ast.GenDecl:
			if n.(*ast.GenDecl).Tok == token.IMPORT {
				return false
			}
		case *ast.ImportSpec:
			return false
		}

		pos := fset.Position(n.Pos())
		end := fset.Position(n.End())
		toks = append(toks, Token{
			Type:    getTypeId(n),
			File:    filename,
			PosLine: pos.Line,
			EndLine: end.Line,
		})
		return true
	})
	return toks
}

type intFlag struct {
	val *int
}

func (f *intFlag) String() string {
	if f.val == nil {
		return "15"
	}
	return strconv.Itoa(*f.val)
}

func (f *intFlag) Set(s string) error {
	v, err := strconv.Atoi(s)
	if err != nil {
		return err
	}
	*f.val = v
	return nil
}

type boolFlag struct {
	val *bool
}

func (f *boolFlag) String() string {
	if f.val == nil {
		return "false"
	}
	return strconv.FormatBool(*f.val)
}

func (f *boolFlag) Set(s string) error {
	v, err := strconv.ParseBool(s)
	if err != nil {
		return err
	}
	*f.val = v
	return nil
}

func (f *boolFlag) IsBoolFlag() bool { return true }

func main() {
	var (
		filesOpt    bool
		htmlOpt     bool
		plumbingOpt bool
		threshold   int = 15
		vendorOpt   bool
		verboseOpt  bool
	)

	flag.BoolVar(&filesOpt, "files", false, "read file names from stdin one at each line")
	flag.BoolVar(&htmlOpt, "html", false, "output the results as HTML, including duplicate code fragments")
	flag.BoolVar(&plumbingOpt, "plumbing", false, "plumbing (easy-to-parse) output for consumption by scripts or tools")
	flag.Var(&intFlag{&threshold}, "t", "minimum token sequence size as a clone (default 15)")
	flag.Var(&intFlag{&threshold}, "threshold", "minimum token sequence size as a clone (default 15)")
	flag.BoolVar(&vendorOpt, "vendor", false, "check files in vendor directory")
	flag.Var(&boolFlag{&verboseOpt}, "v", "explain what is being done")
	flag.Var(&boolFlag{&verboseOpt}, "verbose", "explain what is being done")

	flag.Usage = func() {
		fmt.Fprintf(os.Stderr, "Usage: dupl [flags] [paths]\n\n")
		fmt.Fprintf(os.Stderr, "Paths:\n")
		fmt.Fprintf(os.Stderr, "  If the given path is a file, dupl will use it regardless of\n")
		fmt.Fprintf(os.Stderr, "  the file extension. If it is a directory, it will recursively\n")
		fmt.Fprintf(os.Stderr, "  search for *.go files in that directory.\n\n")
		fmt.Fprintf(os.Stderr, "  If no path is given, dupl will recursively search for *.go\n")
		fmt.Fprintf(os.Stderr, "  files in the current directory.\n\n")
		fmt.Fprintf(os.Stderr, "Flags:\n")
		fmt.Fprintf(os.Stderr, "  -files\n    \tread file names from stdin one at each line\n")
		fmt.Fprintf(os.Stderr, "  -html\n    \toutput the results as HTML, including duplicate code fragments\n")
		fmt.Fprintf(os.Stderr, "  -plumbing\n    \tplumbing (easy-to-parse) output for consumption by scripts or tools\n")
		fmt.Fprintf(os.Stderr, "  -t, -threshold size\n    \tminimum token sequence size as a clone (default 15)\n")
		fmt.Fprintf(os.Stderr, "  -vendor\n    \tcheck files in vendor directory\n")
		fmt.Fprintf(os.Stderr, "  -v, -verbose\n    \texplain what is being done\n\n")
		fmt.Fprintf(os.Stderr, "Examples:\n")
		fmt.Fprintf(os.Stderr, "  dupl -t 100\n    \tSearch clones in the current directory of size at least\n    \t100 tokens.\n")
		fmt.Fprintf(os.Stderr, "  dupl $(find app/ -name '*_test.go')\n    \tSearch for clones in tests in the app directory.\n")
		fmt.Fprintf(os.Stderr, "  find app/ -name '*_test.go' |dupl -files\n    \tThe same as above.\n")
	}

	flag.Parse()

	var filenames []string

	if filesOpt {
		scanner := bufio.NewScanner(os.Stdin)
		for scanner.Scan() {
			line := strings.TrimSpace(scanner.Text())
			if line != "" {
				filenames = append(filenames, line)
			}
		}
	} else {
		args := flag.Args()
		if len(args) == 0 {
			args = []string{"."}
		}

		for _, arg := range args {
			cleanArg := filepath.Clean(arg)
			fi, err := os.Lstat(cleanArg)
			if err != nil {
				log.Println(err)
				os.Exit(1)
			}

			if !fi.IsDir() {
				filenames = append(filenames, cleanArg)
			} else {
				err := filepath.Walk(cleanArg, func(path string, info os.FileInfo, err error) error {
					if err != nil {
						return err
					}
					if info.IsDir() {
						if !vendorOpt && info.Name() == "vendor" {
							return filepath.SkipDir
						}
						return nil
					}
					if strings.HasSuffix(path, ".go") {
						filenames = append(filenames, path)
					}
					return nil
				})
				if err != nil {
					log.Println(err)
					os.Exit(1)
				}
			}
		}
	}

	if verboseOpt {
		log.Println("Building suffix tree")
	}

	fset := token.NewFileSet()
	var allTokens []Token
	var tokenTypes []int
	sentinelID := 100000000

	for fileIdx, fname := range filenames {
		node, err := parser.ParseFile(fset, fname, nil, 0)
		if err != nil {
			log.Println(err)
			continue
		}

		fileToks := extractFileTokens(fset, fname, node)
		if len(fileToks) == 0 {
			continue
		}

		for _, t := range fileToks {
			allTokens = append(allTokens, t)
			tokenTypes = append(tokenTypes, t.Type)
		}

		sTok := Token{
			Type:    sentinelID + fileIdx,
			File:    fname,
			PosLine: 0,
			EndLine: 0,
		}
		allTokens = append(allTokens, sTok)
		tokenTypes = append(tokenTypes, sTok.Type)
	}

	st := NewSuffixTree(tokenTypes)

	if verboseOpt {
		log.Println("Searching for clones")
	}

	rawGroups := st.FindMaximalRepeats(threshold)

	var cloneGroups []CloneGroup

	for _, rg := range rawGroups {
		depth := rg.Depth
		var clones []Clone

		for _, leafIdx := range rg.Leaves {
			if leafIdx+depth > len(allTokens) {
				continue
			}

			startTok := allTokens[leafIdx]
			maxEndLine := 0
			for j := leafIdx; j < leafIdx+depth; j++ {
				if allTokens[j].EndLine > maxEndLine {
					maxEndLine = allTokens[j].EndLine
				}
			}

			clones = append(clones, Clone{
				Filename:  startTok.File,
				StartLine: startTok.PosLine,
				EndLine:   maxEndLine,
			})
		}

		sort.Slice(clones, func(i, j int) bool {
			if clones[i].Filename != clones[j].Filename {
				return clones[i].Filename < clones[j].Filename
			}
			if clones[i].StartLine != clones[j].StartLine {
				return clones[i].StartLine < clones[j].StartLine
			}
			return clones[i].EndLine < clones[j].EndLine
		})

		cloneGroups = append(cloneGroups, CloneGroup{
			Depth:  depth,
			Clones: clones,
		})
	}

	sort.Slice(cloneGroups, func(i, j int) bool {
		if cloneGroups[i].Depth != cloneGroups[j].Depth {
			return cloneGroups[i].Depth > cloneGroups[j].Depth
		}
		if cloneGroups[i].Clones[0].Filename != cloneGroups[j].Clones[0].Filename {
